CREATE TABLE public.connection_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requester_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, recipient_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined')), created_at timestamptz NOT NULL DEFAULT now(), responded_at timestamptz, cancelled_at timestamptz, request_email_sent_at timestamptz, provisioning_claim uuid, provisioning_at timestamptz, CHECK(requester_id<>recipient_id));
GRANT SELECT ON public.connection_requests TO authenticated; GRANT ALL ON public.connection_requests TO service_role;
ALTER TABLE public.connection_requests ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX connection_pair_unique ON public.connection_requests(least(requester_id,recipient_id),greatest(requester_id,recipient_id));
CREATE POLICY connections_read ON public.connection_requests FOR SELECT TO authenticated USING(auth.uid() IN(requester_id,recipient_id) AND public.is_active_member(auth.uid()));
CREATE TABLE public.conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL UNIQUE REFERENCES public.connection_requests(id) ON DELETE CASCADE, conversation_sid text UNIQUE, user_a uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, user_b uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, participant_a_sid text, participant_b_sid text, created_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz, twilio_closed_at timestamptz, CHECK(user_a<>user_b));
GRANT SELECT ON public.conversations TO authenticated; GRANT ALL ON public.conversations TO service_role;
ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY conversations_read ON public.conversations FOR SELECT TO authenticated USING(auth.uid() IN(user_a,user_b) AND public.is_active_member(auth.uid()) AND public.can_view_profile(CASE WHEN auth.uid()=user_a THEN user_b ELSE user_a END));
CREATE TABLE public.message_events (message_sid text PRIMARY KEY, conversation_id uuid NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE, sender_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, recipient_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, message_index integer NOT NULL CHECK(message_index>=0), excerpt text NOT NULL DEFAULT '' CHECK(char_length(excerpt)<=240), created_at timestamptz NOT NULL DEFAULT now(), push_attempted_at timestamptz, UNIQUE(conversation_id,message_index));
GRANT SELECT ON public.message_events TO authenticated; GRANT ALL ON public.message_events TO service_role;
ALTER TABLE public.message_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY events_read ON public.message_events FOR SELECT TO authenticated USING(auth.uid() IN(sender_id,recipient_id) AND EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=conversation_id AND c.closed_at IS NULL));
CREATE TABLE public.conversation_receipts (conversation_id uuid NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, read_index integer NOT NULL DEFAULT -1, last_reminder_index integer, reminder_claim uuid, reminder_claimed_at timestamptz, PRIMARY KEY(conversation_id,user_id));
GRANT SELECT ON public.conversation_receipts TO authenticated; GRANT ALL ON public.conversation_receipts TO service_role;
ALTER TABLE public.conversation_receipts ENABLE ROW LEVEL SECURITY;
CREATE POLICY receipts_read ON public.conversation_receipts FOR SELECT TO authenticated USING(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=conversation_id AND c.closed_at IS NULL));
CREATE TABLE public.push_subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(user_id) ON DELETE CASCADE, endpoint text NOT NULL UNIQUE CHECK(char_length(endpoint)<=2048), p256dh text NOT NULL CHECK(char_length(p256dh)<=300), auth text NOT NULL CHECK(char_length(auth)<=100), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,DELETE ON public.push_subscriptions TO authenticated; GRANT ALL ON public.push_subscriptions TO service_role;
ALTER TABLE public.push_subscriptions ENABLE ROW LEVEL SECURITY;
CREATE POLICY push_read ON public.push_subscriptions FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY push_delete ON public.push_subscriptions FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.request_connection(target uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF target=auth.uid() OR NOT public.is_active_member(auth.uid()) OR NOT public.can_view_profile(target) THEN RAISE EXCEPTION 'Forbidden'; END IF; INSERT INTO public.connection_requests(requester_id,recipient_id) VALUES(auth.uid(),target) ON CONFLICT DO NOTHING RETURNING id INTO result; IF result IS NULL THEN SELECT id INTO result FROM public.connection_requests WHERE least(requester_id,recipient_id)=least(auth.uid(),target) AND greatest(requester_id,recipient_id)=greatest(auth.uid(),target); END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.request_connection(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.request_connection(uuid) TO authenticated;
CREATE FUNCTION public.decline_connection(request uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.connection_requests SET status='declined',responded_at=now() WHERE id=request AND recipient_id=auth.uid() AND status='pending' AND cancelled_at IS NULL AND public.is_active_member(auth.uid()); IF NOT FOUND THEN RAISE EXCEPTION 'Forbidden'; END IF; END $$;
REVOKE ALL ON FUNCTION public.decline_connection(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.decline_connection(uuid) TO authenticated;
CREATE FUNCTION public.block_connection_cleanup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.connection_requests SET cancelled_at=now(),status=CASE WHEN status='pending' THEN 'declined' ELSE status END,responded_at=coalesce(responded_at,now()) WHERE least(requester_id,recipient_id)=least(NEW.blocker_id,NEW.blocked_id) AND greatest(requester_id,recipient_id)=greatest(NEW.blocker_id,NEW.blocked_id); UPDATE public.conversations SET closed_at=coalesce(closed_at,now()) WHERE least(user_a,user_b)=least(NEW.blocker_id,NEW.blocked_id) AND greatest(user_a,user_b)=greatest(NEW.blocker_id,NEW.blocked_id); RETURN NEW; END $$;
CREATE TRIGGER blocks_close_connections AFTER INSERT ON public.blocks FOR EACH ROW EXECUTE FUNCTION public.block_connection_cleanup();
CREATE INDEX message_reminder_due ON public.message_events(recipient_id,created_at);
CREATE FUNCTION public.claim_connection_accept(request uuid, actor uuid, claim uuid) RETURNS public.connection_requests LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result public.connection_requests; BEGIN SELECT * INTO result FROM public.connection_requests WHERE id=request FOR UPDATE; IF result.recipient_id IS DISTINCT FROM actor OR result.status<>'pending' OR result.cancelled_at IS NOT NULL OR NOT public.is_active_member(actor) OR NOT public.is_active_member(result.requester_id) OR EXISTS(SELECT 1 FROM public.blocks WHERE least(blocker_id,blocked_id)=least(result.requester_id,actor) AND greatest(blocker_id,blocked_id)=greatest(result.requester_id,actor)) THEN RAISE EXCEPTION 'Forbidden'; END IF; IF result.provisioning_at>now()-interval '30 seconds' THEN RAISE EXCEPTION 'Busy'; END IF; UPDATE public.connection_requests SET provisioning_claim=claim,provisioning_at=now() WHERE id=request RETURNING * INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.claim_connection_accept(uuid,uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.claim_connection_accept(uuid,uuid,uuid) TO service_role;
CREATE FUNCTION public.finish_connection_accept(request uuid,claim uuid,sid text,pa text,pb text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.connection_requests; result uuid; BEGIN SELECT * INTO r FROM public.connection_requests WHERE id=request FOR UPDATE; IF r.provisioning_claim IS DISTINCT FROM claim OR r.status<>'pending' OR r.cancelled_at IS NOT NULL OR EXISTS(SELECT 1 FROM public.blocks WHERE least(blocker_id,blocked_id)=least(r.requester_id,r.recipient_id) AND greatest(blocker_id,blocked_id)=greatest(r.requester_id,r.recipient_id)) THEN RAISE EXCEPTION 'Cancelled'; END IF; INSERT INTO public.conversations(request_id,conversation_sid,user_a,user_b,participant_a_sid,participant_b_sid) VALUES(r.id,sid,r.requester_id,r.recipient_id,pa,pb) RETURNING id INTO result; INSERT INTO public.conversation_receipts(conversation_id,user_id) VALUES(result,r.requester_id),(result,r.recipient_id); UPDATE public.connection_requests SET status='accepted',responded_at=now(),provisioning_claim=NULL,provisioning_at=NULL WHERE id=request; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.finish_connection_accept(uuid,uuid,text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.finish_connection_accept(uuid,uuid,text,text,text) TO service_role;